drop policy if exists "Customers read evidence for verified POD" on storage.objects;
create policy "Customers read evidence for verified POD" on storage.objects for select to authenticated using (bucket_id='krim-driver-evidence' and exists (select 1 from public.krim_pod_records p join public.krim_shipments s on s.id=p.shipment_id where p.status='verified' and p.verified_at is not null and s.customer_organization_id is not null and private.krim_has_organization_access((select auth.uid()),s.customer_organization_id) and exists (select 1 from jsonb_array_elements(case when jsonb_typeof(p.evidence_metadata->'driver_evidence')='array' then p.evidence_metadata->'driver_evidence' else '[]'::jsonb end) as item where item->>'storage_path'=objects.name)));
